function validateEditable(value:unknown){const result=validatePractice(value);const p=value as PracticeDocument;if(p?.mode==='bank'&&p.totalScore===0&&Array.isArray(p.sections)&&p.sections.length===0){const errors=result.errors.filter(e=>e.path!=='/totalScore'&&e.path!=='/sections');return {valid:!errors.length,errors};}return result;}
