async function download(name:string,content:string|Uint8Array,mime='application/json'){if(mime.startsWith('text/html')&&typeof content==='string')content=await standalonePaperHTML(content);const url=URL.createObjectURL(new Blob([content as BlobPart],{type:mime}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
async function action(button:HTMLButtonElement,fn:()=>void|Promise<void>,label='已完成'){if(button.disabled)return;const old=button.innerHTML;button.disabled=true;button.setAttribute('aria-busy','true');try{await fn();button.innerHTML=`${icon('check')}<span>${label}</span>`;}catch(e){status(e instanceof Error?e.message:String(e),true);button.textContent='重试';}finally{button.disabled=false;button.removeAttribute('aria-busy');setTimeout(()=>{if(button.isConnected)button.innerHTML=old;},2000);}}
async function database(){return new Promise<IDBDatabase>((resolve,reject)=>{const req=indexedDB.open('paper-notebook-practice',1);req.onupgradeneeded=()=>req.result.createObjectStore('workspace');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
async function persist(){const snapshot=structuredClone({document:data,library,artifact,requestedSubset});saveQueue=saveQueue.catch(()=>{}).then(async()=>{try{const db=await database();await new Promise<void>((resolve,reject)=>{const tx=db.transaction('workspace','readwrite');tx.objectStore('workspace').put(snapshot,'current');tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error);});db.close();saveFailed=false;}catch{saveFailed=true;status('本机保存不可用，请下载试卷或题库备份。',true);}});await saveQueue;}
async function restore(){try{const db=await database();const saved=await new Promise<any>((resolve,reject)=>{const req=db.transaction('workspace').objectStore('workspace').get('current');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});db.close();if(saved){const candidate=saved.document??saved.data;if(candidate){const check=validateEditable(candidate);if(check.valid){data=generatedPaper(candidate);paperKind='exam';}else if(candidate.sections?.length)throw Error('上次保存的题库格式有误，请打开备份');}library=saved.library&&validatePractice(saved.library).valid?saved.library:null;artifact=saved.artifact??null;requestedSubset=saved.requestedSubset===true;}}catch(e){status(e instanceof Error?e.message:'无法恢复本机文件',true);}finally{restored=true;root.querySelector<HTMLButtonElement>('#import-top')!.disabled=false;render();}}
