 change('paper-title',value=>{data!.title=value;if(data!.presentation)data!.presentation.titleLines=[value];});change('paper-subject',value=>data!.subject=value);change('paper-level',value=>data!.level=value);change('paper-duration',value=>data!.durationMinutes=Number(value));change('paper-font',value=>{data!.style.fontSize=Number(value);if(data!.style.templateOverrides)delete data!.style.templateOverrides.fontSize;});change('paper-leading',value=>{data!.style.lineHeight=Number(value);if(data!.style.templateOverrides)delete data!.style.templateOverrides.lineHeight;});change('paper-template',value=>{if(value)data=applyPaperTemplate(data!,value);else delete data!.style.templateId;});
